import React from 'react';
import { TabMenu } from 'primereact/tabmenu';
import { useNavigate } from 'react-router-dom';

export default function Router() {
    const navigate = useNavigate();
    const items = [
        { label: 'Router Link', icon: 'pi pi-home', command: () => { navigate('/installation'); } },
        {
            label: 'Programmatic',
            icon: 'pi pi-palette',
            command: () => {
                navigate('/configuration');
            }
        },
        { label: 'External', icon: 'pi pi-link', command: () => { window.location.href = 'https://react.dev/'; } }
    ];

    return (
        <>
            <TabMenu model={items} />
        </>
    )

}